wareness"]}]'::jsonb) AS r(id text, label text, skill_group text, uri text, match text, esco_label text, keywords text[], labels jsonb, alt_labels text[]) ON CONFLICT (id) DO UPDATE SET label = EXCLUDED.label, skill_group = EXCLUDED.skill_group, uri = EXCLUDED.uri, match = EXCLUDED.match, esco_label = EXCLUDED.esco_label, keywords = EXCLUDED.keywords, labels = EXCLUDED.labels, alt_labels = EXCLUDED.alt_labels;

INSERT INTO talent (id, reveal_name, headline, previous_field, availability, mode, position) SELECT id, reveal_name, headline, previous_field, availability, mode, position FROM jsonb_to_recordset('[{"id":"T-01","reveal_name":"Grace Okafor","headline":"Registered nurse from Lagos, in the Finnish licensing process for nurses trained abroad.","previous_field":"Hospital nursing (surgical ward)","availability":"From February","mode":"On-site","position":0},{"id":"T-02","reveal_name":"Pirjo Korhonen","headline":"Practical nurse with 15 years in home care. Calm under pressure.","previous_field":"Home care (lähihoitaja)","availability":"Immediately","mode":"On-site","position":1},{"id":"T-03","reveal_name":"Lucía Martínez","headline":"Front-end developer who tests with screen readers before shipping.","previous_field":"Graphic design","availability":"From February","mode":"Remote","position":2},{"id":"T-04","reveal_name":"Ahmed Hassan","headline":"Grew up in Espoo; six years on the warehouse floor, the last two as acting shift lead.","previous_field":"Warehouse operations","availability":"From January","mode":"On-site","position":3},{"id":"T-05","reveal_name":"Marta Wiśniewska","headline":"Logistics coordinator who keeps carriers, customers and the warehouse on the same page.","previous_field":"Freight forwarding","availability":"Immediately","mode":"Hybrid","position":4},{"id":"T-06","reveal_name":"Daniel Ferreira","headline":"Former chef, now a self-taught back-end developer who writes tests first.","previous_field":"Restaurant kitchen (chef)","availability":"Immediately","mode":"Any","position":5},{"id":"T-07","reveal_name":"Amina Khalil","headline":"Moves messy sensor data into tidy, queryable tables.","previous_field":"Industrial automation","availability":"From January","mode":"Hybrid","position":6},{"id":"T-08","reveal_name":"Liisa Mäkinen","headline":"Nurse turned health informatics specialist; speaks both clinician and developer.","previous_field":"Nursing (emergency department)","availability":"From March","mode":"Hybrid","position":7},{"id":"T-09","reveal_name":"Elina Virtanen","headline":"Former teacher turned junior data analyst.","previous_field":"Teaching (mathematics)","availability":"From January","mode":"Hybrid","position":8},{"id":"T-10","reveal_name":"Wei Zhang","headline":"Recent Aalto MSc graduate; builds forecasting models people actually use.","previous_field":"Master''s thesis (energy demand forecasting)","availability":"Immediately","mode":"Hybrid","position":9},{"id":"T-11","reveal_name":"Kalle Sjöberg","headline":"HVAC technician who can explain a ventilation fault to any tenant.","previous_field":"HVAC maintenance","availability":"From February","mode":"On-site","position":10},{"id":"T-12","reveal_name":"Jari Laine","headline":"Ten years running a warehouse floor, now learning to automate it with data.","previous_field":"Warehouse operations","availability":"Immediately","mode":"On-site","position":11},{"id":"T-13","reveal_name":"Fatima Al-Rashid","headline":"Pharmacist from Baghdad retraining in Finland; strong on medication safety.","previous_field":"Community pharmacy","availability":"From January","mode":"On-site","position":12},{"id":"T-14","reveal_name":"Jonas Becker","headline":"QA engineer who automates the boring checks so humans can test the weird stuff.","previous_field":"Software testing (automotive)","availability":"From March","mode":"Remote","position":13},{"id":"T-15","reveal_name":"Mikko Heikkinen","headline":"Building services engineer, energy audits for older housing companies.","previous_field":"Building services","availability":"From March","mode":"On-site","position":14},{"id":"T-16","reveal_name":"Aino Peltonen","headline":"Ex-barista, bootcamp UX designer. Runs usability tests in cafés.","previous_field":"Hospitality","availability":"Immediately","mode":"Remote","position":15},{"id":"T-17","reveal_name":"Nikolai Ivanov","headline":"Freight dispatcher from Tallinn; keeps 40 trucks moving through bad weather.","previous_field":"Road freight dispatching","availability":"From January","mode":"On-site","position":16},{"id":"T-18","reveal_name":"Oleksandr Petrenko","headline":"Electrician with solar and battery installation experience.","previous_field":"Electrical installation","availability":"Immediately","mode":"On-site","position":17},{"id":"T-19","reveal_name":"Priya Raman","headline":"Cloud security analyst; thinks about what could go wrong so others don''t have to.","previous_field":"IT services (security operations)","availability":"From February","mode":"Hybrid","position":18},{"id":"T-20","reveal_name":"Matti Järvinen","headline":"Ex-Defence Forces logistics NCO moving into civilian project management.","previous_field":"Military logistics","availability":"From January","mode":"On-site","position":19},{"id":"T-21","reveal_name":"Ravi Sharma","headline":"Supply-chain planner who loves a good spreadsheet model.","previous_field":"Manufacturing procurement","availability":"Immediately","mode":"Any","position":20},{"id":"T-22","reveal_name":"Isabel Cruz","headline":"Caregiver with eight years in assisted living in Manila and Espoo.","previous_field":"Assisted living care","availability":"Immediately","mode":"On-site","position":21},{"id":"T-23","reveal_name":"Tuomas Lehtonen","headline":"Ex-musician, self-taught analyst who makes dashboards people open on Mondays.","previous_field":"Music & event production","availability":"From February","mode":"Hybrid","position":22},{"id":"T-24","reveal_name":"Sofia Nyström","headline":"Full-stack bootcamp graduate with a background in customer support.","previous_field":"Customer support","availability":"From January","mode":"Remote","position":23},{"id":"T-27","reveal_name":"Hanna Richter","headline":"Sustainability coordinator who made ESG reporting less painful.","previous_field":"Retail operations","availability":"Immediately","mode":"Hybrid","position":24},{"id":"T-30","reveal_name":"Thanh Nguyen","headline":"Cloud data engineer, likes boring reliable pipelines.","previous_field":"Banking IT","availability":"From February","mode":"Hybrid","position":25}]'::jsonb) AS r(id text, reveal_name text, headline text, previous_field text, availability text, mode text, position int);

